package com.gamehub.application.controller;
import com.gamehub.application.OperationsService;
public final class TeamController { private final OperationsService ops; public TeamController(OperationsService ops){this.ops=ops;} public long create(long captain,String name)throws Exception{return ops.createTeam(captain,name);} public void request(long team,long customer)throws Exception{ops.requestJoin(team,customer);} public void decide(long captain,long team,long customer,boolean approve)throws Exception{ops.decideJoin(captain,team,customer,approve);} }